const body = $input.first().json.body || {};
const text = typeof body.text === 'string' ? body.text.trim() : '';
const sessionId = typeof body.sessionId === 'string' && /^[a-zA-Z0-9_-]{1,64}$/.test(body.sessionId) ? body.sessionId : 'local-test';
const output = !text ? 'Please send your trip request as text.' : text.length > 4000 ? 'Please shorten your message to 4000 characters or less.' : /^\s*(hi|hello|hey)\s*[!.]?\s*$/i.test(text) ? "Hi, I'm Glide. I can help plan a vacation, business trip, or everyday journey. Where are you thinking of going?" : /\b(book|buy|purchase|pay|cancel|change|reschedule|modify)\b/i.test(text) ? "I can help prepare that, but live booking and payment connections are not active yet, so I can't complete purchases, cancellations, or reservation changes. Share the trip dates and any reservation reference, and I'll organize the next step. Before a future action, I'll show the exact option, total price, fees, and terms for your approval." : '';
return [{ json: { text, sessionId: 'local:' + sessionId, channel: 'local', ...(output ? { output } : {}) } }];

